    s=json.loads((PUBLIC/'summary.json').read_text());gate=json.loads((PUBLIC/'ledger-gate.json').read_text());export=json.loads((PUBLIC/'ledger-export.json').read_text());lines=[];add=lambda line='':lines.append(line)
    add('# H3bf: selected hard-tail failures persist across new source banks');add()
    add('**The primary is falsified: only six of the twenty-two selected truths reach the required 48 exact identifications in 64 fresh banks.** Across this explicitly postselected failure set, 704/1,408 banks identify the exact model within four membership queries. Every truth has 64 distinct unordered source banks.');add()
    add('![Selected-tail robustness](../../../../results/research/loki/h3bf/hard-tail-robustness.png)');add()
